const fs = require('fs');
const path = require('path');

const excludeDirs = ['.git', '.github', 'node_modules'];
const excludeFiles = ['search.json'];

function scanDir(dir, baseDir = dir) {
    let results = [];
    const list = fs.readdirSync(dir);

    list.forEach(file => {
        const filePath = path.join(dir, file);
        const relativePath = path.relative(baseDir, filePath).replace(/\\/g, '/');
        const stat = fs.statSync(filePath);

        if (stat.isDirectory()) {
            if (!excludeDirs.includes(file)) {
                results = results.concat(scanDir(filePath, baseDir));
            }
        } else {
            const ext = path.extname(file).toLowerCase();
            if (!['.png', '.jpg', '.jpeg', '.webp'].includes(ext) && !excludeFiles.includes(relativePath)) {
                try {
                    const content = fs.readFileSync(filePath, 'utf8');
                    let title = relativePath;
                    let textContent = content;

                    if (ext === '.html') {
                        const titleMatch = content.match(/<title>(.*?)<\/title>/i);
                        if (titleMatch) title = titleMatch[1];

                        textContent = content.replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '')
                                             .replace(/<style\b[^<]*(?:(?!<\/style>)<[^<]*)*<\/style>/gi, '')
                                             .replace(/<[^>]+>/g, ' ')
                                             .replace(/\s+/g, ' ')
                                             .trim();
                    }

                    results.push({
                        url: relativePath,
                        title: title,
                        content: textContent
                    });
                } catch (e) {}
            }
        }
    });

    return results;
}

const searchData = scanDir('.');
fs.writeFileSync('search.json', JSON.stringify(searchData, null, 2));
console.log('search.json generated successfully!');

let searchIndex = [];

// ページ読み込み時に自動生成された search.json を取得
fetch('search.json')
    .then(response => response.json())
    .then(data => {
        searchIndex = data;
    })
    .catch(err => console.error('検索インデックスの読み込みに失敗しました:', err));

function autoSearch(keyword) {
    const popup = document.getElementById("search-results-popup");
    const query = keyword.trim().toLowerCase();

    if (!query) {
        popup.style.display = "none";
        popup.innerHTML = "";
        return;
    }

    // タイトルや本文にキーワードが含まれているものを抽出
    const matches = searchIndex.filter(page => 
        page.title.toLowerCase().includes(query) || page.content.toLowerCase().includes(query)
    );

    if (matches.length === 0) {
        popup.style.display = "block";
        popup.innerHTML = `<div style="padding: 10px; font-size: 0.9rem; color: #54595d;">一致するページはありません</div>`;
        return;
    }

    let html = "<ul style='list-style: none; margin: 0; padding: 0;'>";
    matches.forEach(page => {
        html += `<li style='border-bottom: 1px solid #eaecf0; background: #fff;'>
            <a href="${page.url}" style='display: block; padding: 8px 10px; text-decoration: none; color: #0645ad; font-size: 0.9rem;'>
                <strong>${page.title}</strong>
            </a>
        </li>`;
    });
    html += "</ul>";

    popup.innerHTML = html;
    popup.style.display = "block";
}

// ページの外側をクリックしたらポップアップを閉じる親切設計
document.addEventListener('click', (e) => {
    const popup = document.getElementById("search-results-popup");
    const input = document.getElementById("search-input");
    if (popup && input && !popup.contains(e.target) && e.target !== input) {
        popup.style.display = "none";
    }
});

/* 全体のリセット設定 */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
}

body {
    background-color: #f8f9fa;
    color: #202122;
    font-size: 14px;
    line-height: 1.6;
}

/* =========================================
   Wikipedia風リンク設定
========================================= */

a {
    color: #0645ad;
    text-decoration: none;
}

a:visited {
    color: #0b0080;
}

a:hover {
    text-decoration: underline;
}

a:active {
    color: #faa700;
}

/* 上部ヘッダー */
.top-bar {
    background-color: #ffffff;
    height: 55px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0 20px;
    border-bottom: 1px solid #a2a9b1;
    position: fixed;
    top: 0;
    width: 100%;
    z-index: 100;
}

.logo-area {
    display: flex;
    flex-direction: column;
}

.wiki-title {
    font-size: 1.15rem;
    font-weight: bold;
    color: #000000;
}

.wiki-subtitle {
    font-size: 0.7rem;
    color: #54595d;
    margin-top: -2px;
}

.search-box input {
    padding: 6px 12px;
    width: 220px;
    border: 1px solid #a2a9b1;
    border-radius: 2px;
    font-size: 0.85rem;
}

.search-box input:focus {
    border-color: #3366cc;
    outline: none;
}

/* メインレイアウト */
.container {
    display: flex;
    margin-top: 55px;
    min-height: calc(100vh - 55px);
}

/* 左側ナビゲーション */
.side-nav {
    width: 190px;
    background-color: #f8f9fa;
    padding: 20px 10px 20px 20px;
    flex-shrink: 0;
}

.nav-section {
    margin-bottom: 20px;
}

.side-nav .nav-title {
    font-size: 0.75rem;
    color: #54595d;
    font-weight: bold;
    border-bottom: 1px solid #eaecf0;
    padding-bottom: 3px;
    margin-bottom: 6px;
    letter-spacing: 0.5px;
}

.side-nav ul {
    list-style: none;
}

.side-nav li {
    margin-bottom: 5px;
}

/* 右側メインコンテンツ */
.main-content {
    flex: 1;
    background-color: #ffffff;
    padding: 30px 40px;
    border-left: 1px solid #a2a9b1;
}

.page-title {
    font-family: 'Linux Libertine', 'Georgia', 'Times New Roman', serif;
    font-weight: normal;
    font-size: 1.8rem;
    border-bottom: 1px solid #a2a9b1;
    padding-bottom: 3px;
    margin-bottom: 15px;
}

.lead-text {
    font-size: 1rem;
    margin-bottom: 20px;
}

h2 {
    font-family: 'Linux Libertine', 'Georgia', serif;
    font-weight: normal;
    font-size: 1.4rem;
    border-bottom: 1px solid #a2a9b1;
    padding-bottom: 3px;
    margin-top: 30px;
    margin-bottom: 12px;
}

p,
ul {
    margin-bottom: 15px;
}

ul {
    padding-left: 20px;
}

li {
    margin-bottom: 4px;
}

/* 免責事項ボックス */
.wiki-notice {
    background-color: #ffffff;
    border: 1px solid #a2a9b1;
    border-left: 4px solid #d33;
    padding: 12px 15px;
    margin: 20px 0;
    font-size: 0.9rem;
}

.notice-title {
    font-weight: bold;
    color: #d33;
    margin-bottom: 3px;
}

/* メイン画像エリア */
.main-visual-container {
    width: 100%;
    text-align: center;
    margin: 20px 0;
    background-color: #f8f9fa;
    border: 1px solid #a2a9b1;
    padding: 8px;
}

.main-visual-img {
    max-width: 100%;
    height: auto;
    display: block;
    margin: 0 auto;
}

/* グリッドレイアウト */
.content-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
    gap: 15px;
    margin: 20px 0;
}

.content-card {
    background-color: #f8f9fa;
    border: 1px solid #a2a9b1;
    padding: 15px;
    border-radius: 2px;
}

.content-card h3 {
    font-size: 1rem;
    margin-bottom: 8px;
}

.content-card p {
    font-size: 0.85rem;
    color: #202122;
    margin-bottom: 0;
}

/* スマホ対応 */
@media (max-width: 768px) {
    .container {
        flex-direction: column;
    }

    .side-nav {
        width: 100%;
        order: 2;
        border-top: 1px solid #a2a9b1;
        padding: 20px;
        background-color: #f8f9fa;
    }

    .main-content {
        width: 100%;
        border-left: none;
        padding: 20px;
        order: 1;
    }

    .search-box input {
        width: 140px;
    }

    .page-title {
        font-size: 1.5rem;
    }
}
